// The page book-edit: Change a book. It loads its record through
// getBook, sends its fields to changeBook and opens book-view once it
// succeeds.

import { BOOK_EDIT_SUBMITTED, BOOK_EDIT_REFUSED } from "./events.js";
import { form } from "./form.js";

form({
  submit: {
    operation: "changeBook",
    method: "PUT",
    path: (parameters) => `/books/${encodeURIComponent(parameters.bookId)}`,
    sent: ["book_title", "shelf_name", "keeper_id", "keeper_name", "shelf_place"],
  },
  source: { operation: "getBook", path: (parameters) => `/books/${encodeURIComponent(parameters.bookId)}` },
  checks: [
    { field: "book_title", rule: (record) => [...(record.book_title ?? [])].length >= 2, message: "A title has two letters or more." },
  ],
  conditions: {
    shelf_name: { readOnlyWhen: (record) => [...(record.book_title ?? [])].length === 0 },
  },
  pickers: {
    keeper_id: { path: "/keepers", items: "items", pageSize: ["page_size", 50], search: "search", value: "keeper_id", shows: ["full_name"], fills: { keeper_name: "full_name" } },
  },
  next: {
    success: { page: "book-view", with: { bookId: "book_id" }, message: "The book is changed." },
  },
  messages: {
    failed: "This cannot be done right now. Try again in a moment.",
    pattern: "This is not in the form it takes.",
    twice: "The two entries are not the same.",
  },
  // What the operations' refusals say, by status, and the field each is about.
  refusals: {
    submit: {
      "404": { message: "There is no such book." },
      "409": { message: "Another book has this title.", field: "book_title" },
    },
    source: {
      "404": "There is no such book.",
    },
  },
  submitted: BOOK_EDIT_SUBMITTED,
  refused: BOOK_EDIT_REFUSED,
});
